script:
frappe.ui.form.on('Purchase Invoice', {
    before_load: function(frm) {
        if (frm.doc.items && frm.doc.items[0].purchase_receipt) {
            // Get the purchase_receipt from the first item
            var purchase_receipt = frm.doc.items[0].purchase_receipt;

            // Fetch the required fields from the Purchase Receipt document
            frappe.db.get_value('Purchase Receipt', purchase_receipt, ['supplier_delivery_note', 'custom_supplier_delivery_note_date'])
                .then(r => {
                    var purchase_receipt_doc = r.message;
                    if (purchase_receipt_doc) {
                        // Set these fetched values to fields in the doc
                        frm.set_value('bill_no', purchase_receipt_doc.supplier_delivery_note);
                        frm.set_value('bill_date', purchase_receipt_doc.custom_supplier_delivery_note_date);
                        // Refresh the fields to ensure they are updated in the UI
                        frm.refresh_field('bill_no');
                        frm.refresh_field('bill_date');
                    }
                });
        }
    }
});

frappe.ui.form.on('BOM', {
	refresh: function(frm) {
		frm.set_query('bom_no', 'items', function(doc, cdt, cdn) {
			let row = locals[cdt][cdn];
			return {
				filters: {
					item: row.item_code,
					is_active: 1,
					docstatus: 1,
					custom_source_warehouse: frm.doc.custom_source_warehouse,
				}
			};
		});
	}
});

frappe.ui.form.on("BMR-Batch Manufacturing Report", {

    refresh: function(frm) {

        // ---------- Helper function for Line Clearance ----------
        const populate_line_clearance = (template_name) => {
            if (!template_name) return;

            frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Line Clearance for Dispensing Area", name: template_name },
                callback: function(res) {
                    if (res.message) {
                        setTimeout(() => {
                            frm.clear_table("line_clearance");

                            (res.message.line_clearance || []).forEach(row => {
                                let child = frm.add_child("line_clearance");
                                child.check_point = row.check_point;
                                child.production = row.production;
                                child.quality = row.quality;
                            });

                            frm.refresh_field("line_clearance");
                        }, 100);
                    }
                }
            });
        };

        // ---------- Helper function for Sieve Integrity ----------
        const populate_sieve = (template_name) => {
            if (!template_name) return;

            frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Sieve Integrity Template", name: template_name },
                callback: function(res) {
                    if (res.message) {
                        setTimeout(() => {
                            frm.clear_table("sieve_integrity_template_results");

                            (res.message.sieve || []).forEach(row => {
                                let child = frm.add_child("sieve_integrity_template_results");
                                child.check_point = row.check_point;
                                child.remark_1 = row.remark_1;
                                child.remark_2 = row.remark_2;
                                child.remark_3 = row.remark_3;
                                child.remark_4 = row.remark_4;
                            });

                            frm.refresh_field("sieve_integrity_template_results");
                        }, 100);
                    }
                }
            });
        };

        // ---------- Helper function for Enclosure ----------
        const populate_enclosure = (template_name) => {
            if (!template_name) return;

            frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Enclosures Template", name: template_name },
                callback: function(res) {
                    if (res.message) {
                        setTimeout(() => {
                            frm.clear_table("enclosure_checkpoint");

                            (res.message.enclosure_template || []).forEach(row => {
                                let child = frm.add_child("enclosure_checkpoint");
                                child.enclosure_checkpoint = row.enclosure_checkpoint;
                                child.status = row.status;
                            });

                            frm.refresh_field("enclosure_checkpoint");
                        }, 100);
                    }
                }
            });
        };

        // ---------- Populate Line Clearance if empty ----------
        if (!frm.doc.line_clearance || frm.doc.line_clearance.length === 0) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Line Clearance for Dispensing Area",
                    filters: { is_default: 1 },
                    limit_page_length: 1,
                    fields: ["name"]
                },
                callback: function(r) {
                    if (r.message && r.message.length > 0) {
                        populate_line_clearance(r.message[0].name);
                    }
                }
            });
        }

        // ---------- Populate Sieve Integrity if empty ----------
        if (!frm.doc.sieve_integrity_template_results || frm.doc.sieve_integrity_template_results.length === 0) {

            let template_name = frm.doc.sieve_integrity_template;

            if (!template_name) {
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Sieve Integrity Template",
                        filters: { is_default: 1 },
                        limit_page_length: 1,
                        fields: ["name"]
                    },
                    callback: function(r) {
                        if (r.message && r.message.length > 0) {
                            populate_sieve(r.message[0].name);
                        }
                    }
                });
            } else {
                populate_sieve(template_name);
            }
        }

        // ---------- Populate Enclosure if empty ----------
        if (!frm.doc.enclosure_checkpoint || frm.doc.enclosure_checkpoint.length === 0) {

            let template_name = frm.doc.enclosure_template;

            if (!template_name) {
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Enclosures Template",
                        filters: { is_default: 1 },
                        limit_page_length: 1,
                        fields: ["name"]
                    },
                    callback: function(r) {
                        if (r.message && r.message.length > 0) {
                            populate_enclosure(r.message[0].name);
                        }
                    }
                });
            } else {
                populate_enclosure(template_name);
            }
        }

        // ---------- Fetch Flowchart Description on refresh ----------
        if (frm.doc.product_code) {
            fetch_flowchart(frm);
        }

    },

    // ---------- Trigger when product_code changes ----------
    product_code: function(frm) {
        if (frm.doc.product_code) {
            fetch_flowchart(frm);
        }
    }

});

// ---------- Helper function to fetch flowchart ----------
function fetch_flowchart(frm) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Flow Chart of Manufacturing Process",
            filters: { item_code: frm.doc.product_code },
            fields: ["description"],
            limit: 1
        },
        callback: function(res) {
            if (res.message && res.message.length > 0) {
                frm.set_value("flowchart", res.message[0].description);
            } else {
                frm.set_value("flowchart", "");

            }
        }
    });
}

frappe.ui.form.on("QC Sensory Test", {
    refresh: function(frm) {

        // ---------- Helper function to populate QC Sensory Template ----------
        const populate_qc = (template_name) => {
            if (!template_name) return;

            frappe.call({
                method: "frappe.client.get",
                args: { doctype: "QC Sensory Template", name: template_name },
                callback: function(res) {
                    if (res.message) {
                        setTimeout(() => {
                            // Clear existing rows in BMR child table
                            frm.clear_table("qc_sensory_template");

                            // Loop through child table in the template
                            (res.message.qc_sensory_template || []).forEach(row => {
                                let child = frm.add_child("qc_sensory_template");
                                child.properties = row.properties;
                                child.in_process_when_int_is_being_made = row.in_process_when_int_is_being_made;
                                child.bulk_analysis_when_int_is_completed = row.bulk_analysis_when_int_is_completed;
                                child.finished_good_when_znut_is_being_packed = row.finished_good_when_znut_is_being_packed;
                            });

                            // Refresh the field to show changes
                            frm.refresh_field("qc_sensory_template");
                        }, 100);
                    }
                }
            });
        };

        // ---------- Auto populate if BMR child table is empty ----------
        if (!frm.doc.qc_sensory_template || frm.doc.qc_sensory_template.length === 0) {

            let template_name = frm.doc.template; // Template selected in form

            // If no template is selected, fetch the default
            if (!template_name) {
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "QC Sensory Template",
                        filters: { is_default: 1 },
                        limit_page_length: 1,
                        fields: ["name"]
                    },
                    callback: function(r) {
                        if (r.message && r.message.length > 0) {
                            populate_qc(r.message[0].name); // Populate using default
                        }
                    }
                });
            } else {
                populate_qc(template_name); // Populate using selected template
            }
        }

    }
});

frappe.ui.form.on("BMR-Batch Manufacturing Report", {
    refresh: function(frm) {
        if (frm.doc.product_code && !frm.doc.label_claim) {
            fetch_label_claim(frm);
        }
    },

    product_code: function(frm) {
        if (frm.doc.product_code) {
            fetch_label_claim(frm);
        }
    }
});

function fetch_label_claim(frm) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Label Claim",
            filters: {
                item_code: frm.doc.product_code,
                docstatus: 1 // ✅ Only submitted records
            },
            fields: ["name"],
            order_by: "modified desc", // fetch latest submitted one
            limit_page_length: 1
        },
        callback: function(res) {
            if (!res.message?.length) {
                frappe.msgprint("No submitted Label Claim found for this product.");
                return;
            }

            const label_claim_name = res.message[0].name;
            frm.set_value("label_claim", label_claim_name);

            frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Label Claim", name: label_claim_name },
                callback: function(r) {
                    if (!r.message) return;
                    const label_claim = r.message;

                    const copy_child_table = (source, target_fieldname) => {
                        frm.clear_table(target_fieldname);
                        (source || []).forEach(row => {
                            let child = frm.add_child(target_fieldname);
                            for (let key in row) {
                                if (![
                                    "name", "owner", "creation", "modified",
                                    "modified_by", "parent", "parentfield",
                                    "parenttype", "idx", "doctype"
                                ].includes(key)) {
                                    child[key] = row[key];
                                }
                            }
                        });
                        frm.refresh_field(target_fieldname);
                    };

                    // ✅ Copy all tables including vitamins & minerals
                    copy_child_table(label_claim.nutritional_information, "nutritional_information");
                    copy_child_table(label_claim.typical_amino_acid_profile, "typical_amino_acid_profile");
                    copy_child_table(label_claim.specific_amino_acids_profile, "specific_amino_acids_profile");
                    copy_child_table(label_claim.added_vitamins, "added_vitamins");
                    copy_child_table(label_claim.added_minerals, "added_minerals");
                }
            });
        }
    });
}

frappe.ui.form.on("Item", {
    refresh: function(frm) {
        // Auto-fetch Label Claim if not already set
        if (frm.doc.item_code && !frm.doc.custom_label_claim) {
            fetch_label_claim_for_item(frm);
        }
    },

    item_code: function(frm) {
        // Fetch when item_code is changed
        if (frm.doc.item_code) {
            fetch_label_claim_for_item(frm);
        }
    }
});

function fetch_label_claim_for_item(frm) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Label Claim",
            filters: { item_code: frm.doc.custom_listing_id },
            fields: ["name", "item_code"]
        },
        callback: function(res) {
            if (!res.message || res.message.length === 0) {
                return;
            }

            const label_claim_name = res.message[0].name;

            // Set the custom_label_claim field
            frm.set_value("custom_label_claim", label_claim_name);

            // Optionally auto-save the item
            frappe.timeout(0.5).then(() => frm.save());
        }
    });
}

frappe.ui.form.on("Vehicle Inspection Checklist", {
    refresh: function(frm) {

        // Only populate if the table is empty
        if (!frm.doc.checkpoints || frm.doc.checkpoints.length === 0) {

            // Step 1: Get default template
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Vehicle Inspection Checklist Template",
                    filters: { is_default: 1 },
                    limit_page_length: 1,
                    fields: ["name"]
                },
                callback: function(r) {
                    if (r.message && r.message.length > 0) {
                        const template_name = r.message[0].name;

                        // Step 2: Fetch full template including child table
                        frappe.call({
                            method: "frappe.client.get",
                            args: {
                                doctype: "Vehicle Inspection Checklist Template",
                                name: template_name
                            },
                            callback: function(res) {
                                if (res.message) {

                                    // Clear existing checkpoints
                                    frm.clear_table("checkpoints");

                                    // Loop through template's child table 'checklists'
                                    (res.message.checklists || []).forEach(function(row) {
                                        let child = frm.add_child("checkpoints");

                                        // Copy all matching fields from template row to checklist row
                                        Object.keys(row).forEach(function(key) {
                                            if (child.hasOwnProperty(key)) {
                                                child[key] = row[key];
                                                child.checkpoints = row.checkpoints;
                                                child.ok__not_ok = row.ok__not_ok;
                                                child.remarks = row.remarks;
                                            }
                                        });
                                    });

                                    frm.refresh_field("checkpoints");
                                }
                            }
                        });

                    } else {
                        console.log("No default Vehicle Inspection Checklist Template found!");
                    }
                }
            });

        }

    }
});
